<?php
declare(strict_types=1);

namespace LifeOS;

/**
 * New member Account IDs are 6-digit numbers (e.g. 482913), generated by the server; they cannot be chosen.
 * Imported/older members keep their LID-2026-… IDs.
 * The Register Form shows a signed preview; registration keeps that ID only if the signature is valid
 * and the ID is still free, otherwise it assigns a fresh one. The same ID is the Life ID and login name.
 */
final class Username
{
    public const PREFIX = 'LID-2026-';
    public const PATTERN = '/^[1-9]\d{5}$/';
    private const TTL = 7200;

    public static function taken(string $name): bool
    {
        // A converted LO######## member owns the same number, so its old form also counts as taken; a
        // 6-digit ID is also refused when an older member already has the same digits as LID-2026-<digits>.
        $legacy = preg_match('/^LID-2026-(\d{8})$/', $name, $m) ? 'LO' . $m[1] : (preg_match(self::PATTERN, $name) ? self::PREFIX . $name : $name);
        return (bool) DB::one('SELECT id FROM users WHERE username = ? OR life_id = ? OR life_id = ? OR referral_code = ? OR phone = ? LIMIT 1', [$name, $name, $legacy, $name, $name]);
    }

    public static function generate(): string
    {
        for ($i = 0; $i < 80; $i++) {
            $name = (string) random_int(100000, 999999);
            if (!self::taken($name)) return $name;
        }
        throw new HttpError('Unable to generate an Account ID, please try again', 503);
    }

    /**
     * Canonical form of a typed Account ID: "lid2026937ccc" -> "LID-2026-937CCC", and a pre-change
     * "LO12345678" -> "LID-2026-12345678". Anything else is returned unchanged.
     */
    public static function normalize(string $id): string
    {
        $id = trim($id);
        if (preg_match('/^LID-?(\d{4})-?([A-Z0-9]+)$/i', $id, $m)) return strtoupper("LID-{$m[1]}-{$m[2]}");
        if (preg_match('/^LO(\d{8})$/i', $id, $m)) return self::PREFIX . $m[1];
        return $id;
    }

    /** @return array{username: string, username_token: string} */
    public static function preview(): array
    {
        $name = self::generate();
        $exp = time() + self::TTL;
        return ['username' => $name, 'username_token' => $exp . '.' . self::sign($name, $exp)];
    }

    /** Returns the previewed ID when the token is genuine, unexpired and the ID is still free; null otherwise. */
    public static function fromToken(string $name, string $token): ?string
    {
        if (!preg_match(self::PATTERN, $name) || !preg_match('/^(\d{10})\.([a-f0-9]{64})$/', $token, $m)) return null;
        if ((int) $m[1] < time() || !hash_equals(self::sign($name, (int) $m[1]), $m[2])) return null;
        return self::taken($name) ? null : $name;
    }

    private static function sign(string $name, int $exp): string
    {
        return hash_hmac('sha256', 'username|' . $name . '|' . $exp, (string) Config::get('app_secret'));
    }
}
